toolCalls.input:
{"command": "p="$TMPDIR/proto"; mkdir -p "$p/bin" && cat > "$p/bin/notes" <<'EOF'
#!/usr/bin/env bash
set -euo pipefail
file="${NOTES_FILE:-$HOME/.notes}"
usage() { echo "usage: notes add <text> | notes list | notes search <word>" >&2; exit 2; }
case "${1:-}" in
  add) shift; printf '%s\n' "$*" >> "$file" ;;
  list) [ -f "$file" ] && cat "$file" || true ;;
  search)
